    );
    let metadata = index.get_metadata(&txn).await.unwrap().unwrap();
    let query_simhash = Layer0QuerySimHash::Computed(
        index
            .simhash_cache(3)
            .unwrap()
            .simhasher()
            .hash_from_slice(&[1.0, 0.0, 0.0])
