//! Behavioural oracle for [`VectorMemoryStore`].
//!
//! These tests pin what callers observe through the store boundary: lookup
//! bytes for every row kind and layer, upsert and removal semantics, hydration
//! admission order, and safety of concurrent lookups during removal. They use
//! only the public store surface so they hold for any resident layout.

use std::collections::{BTreeMap, HashMap};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

use bytes::Bytes;
use proptest::prelude::*;
use slatedb::object_store::memory::InMemory;
use slatedb::{Db, IsolationLevel};

use super::*;
use crate::encoding::v2::keys::indexes::vector::{
    VectorLayer0NeighborsKey, VectorSimHashKey, VectorUpperNeighborsKey, VectorUpperVectorKey,
};
use crate::encoding::v2::keys::scope::TenantId;

/// Highest layer the generated fixtures use; lookups probe one layer above it.
const MAX_LAYER: u16 = 4;

/// One supported cache row together with the exact persisted key it came from.
#[derive(Debug, Clone, PartialEq, Eq)]
enum ExpectedRow {
    Neighbors {
        layer: u16,
        node_id: NodeId,
        value: Bytes,
    },
    SimHash {
        node_id: NodeId,
        bits: u64,
    },
    Vector {
        node_id: NodeId,
        value: Bytes,
    },
}

/// Deterministic SplitMix64 stream so fixtures are reproducible without seeds.
struct SplitMix(u64);

impl SplitMix {
    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    fn bytes(&mut self, len: usize) -> Bytes {
        (0..len)
            .map(|_| self.next().to_le_bytes()[0])
            .collect::<Vec<u8>>()
            .into()
    }
}

/// Reference model of every row a store should currently return.
#[derive(Debug, Default)]
struct Model {
    vectors: HashMap<NodeId, Bytes>,
    neighbors: HashMap<(u16, NodeId), Bytes>,
    simhashes: HashMap<NodeId, u64>,
}

impl Model {
    fn admit(&mut self, row: &ExpectedRow) {
        match row {
            ExpectedRow::Neighbors {
                layer,
                node_id,
                value,
            } => {
                self.neighbors.insert((*layer, *node_id), value.clone());
            }
            ExpectedRow::SimHash { node_id, bits } => {
                self.simhashes.insert(*node_id, *bits);
            }
            ExpectedRow::Vector { node_id, value } => {
                self.vectors.insert(*node_id, value.clone());
            }
        }
    }

    fn remove_node(&mut self, node_id: NodeId) {
        self.vectors.remove(&node_id);
        self.simhashes.remove(&node_id);
        self.neighbors.retain(|(_, node), _| *node != node_id);
    }

    /// Asserts every lookup for `nodes` and layers `0..=MAX_LAYER + 1`.
    fn assert_matches(&self, store: &VectorMemoryStore, nodes: impl IntoIterator<Item = NodeId>) {
        for node_id in nodes {
            assert_eq!(
                store.get_upper_vector(node_id),
                self.vectors.get(&node_id).cloned(),
                "upper vector for node {node_id}"
            );
            assert_eq!(
                store.get_simhash(node_id).map(|hash| hash.bits()),
                self.simhashes.get(&node_id).copied(),
                "simhash for node {node_id}"
            );
            for layer in 0..=MAX_LAYER + 1 {
                assert_eq!(
                    store.get_upper_neighbors_bytes(layer, node_id),
                    self.neighbors.get(&(layer, node_id)).cloned(),
                    "upper neighbors for node {node_id} layer {layer}"
                );
            }
        }
    }
}

/// Builds the persisted key bytes for one expected row in `scope`.
fn row_key(scope: DataScope, index_id: u64, row: &ExpectedRow) -> Bytes {
    let key = match row {
        ExpectedRow::Neighbors { layer, node_id, .. } => {
            VectorKey::UpperNeighbors(VectorUpperNeighborsKey::new(index_id, *layer, *node_id))
        }
        ExpectedRow::SimHash { node_id, .. } => {
            VectorKey::SimHash(VectorSimHashKey::new(index_id, *node_id))
        }
        ExpectedRow::Vector { node_id, .. } => {
            VectorKey::UpperVector(VectorUpperVectorKey::new(index_id, *node_id))
        }
    };
    DataKey::Data {
        scope,
        kind: DataKeyKind::Vector(key),
    }
    .to_bytes()
}

/// Persisted value bytes for one expected row.
fn row_value(row: &ExpectedRow) -> Bytes {
    match row {
        ExpectedRow::Neighbors { value, .. } | ExpectedRow::Vector { value, .. } => value.clone(),
        ExpectedRow::SimHash { bits, .. } => Bytes::copy_from_slice(&encode_simhash(*bits)),
    }
}

/// An HNSW-shaped fixture: every node has a SimHash, roughly one in eight
/// nodes has upper layers, and upper rows vary from empty to multi-MiB.
struct HydrationFixture {
    db: Db,
    scope: DataScope,
    index_id: u64,
    node_count: NodeId,
    /// Supported rows in physical scan (key) order.
    rows: Vec<ExpectedRow>,
}

impl HydrationFixture {
    async fn build(name: &str, node_count: NodeId) -> Self {
        let scope = DataScope::Tenant(TenantId::from_u128(0xC0FFEE));
        let index_id = crate::search::vector::index_id_from_name(name);
        let db = Db::builder(name, Arc::new(InMemory::new()))
            .build()
            .await
            .expect("fixture db opens");
        let mut random = SplitMix(index_id);
        let mut rows = Vec::new();
        for node_id in 0..node_count {
            rows.push(ExpectedRow::SimHash {
                node_id,
                bits: random.next(),
            });
            let level = match node_id {
                id if id % 512 == 0 => MAX_LAYER,
                id if id % 64 == 0 => 2,
                id if id % 8 == 0 => 1,
                _ => 0,
            };
            for layer in 1..=level {
                let len = usize::try_from(random.next() % 200).unwrap();
                rows.push(ExpectedRow::Neighbors {
                    layer,
                    node_id,
                    value: random.bytes(len),
                });
            }
            if level > 0 {
                // Node 8 carries a row larger than any plausible chunk, node
                // 16 an empty row; the rest are vector-sized.
                let len = match node_id {
                    8 => 3 * 1024 * 1024 + 7,
                    16 => 0,
                    _ => 64 + usize::try_from(random.next() % 1200).unwrap(),
                };
                rows.push(ExpectedRow::Vector {
                    node_id,
                    value: random.bytes(len),
                });
            }
        }
        rows.sort_by_key(|row| row_key(scope, index_id, row));

        let transaction = db.begin(IsolationLevel::Snapshot).await.unwrap();
        for row in &rows {
            transaction
                .put(row_key(scope, index_id, row), row_value(row))
                .unwrap();
        }
        // Rows hydration must skip: layer-0 neighbors in the same prefix, a
        // different index, and the same index in a different scope.
        for node_id in 0..node_count {
            transaction
                .put(
                    DataKey::Data {
                        scope,
                        kind: DataKeyKind::Vector(VectorKey::Layer0Neighbors(
                            VectorLayer0NeighborsKey::new(index_id, node_id),
                        )),
                    }
                    .to_bytes(),
                    random.bytes(48),
                )
                .unwrap();
        }
        let foreign_vector = ExpectedRow::Vector {
            node_id: 8,
            value: Bytes::from_static(b"foreign"),
        };
        transaction
            .put(
                row_key(scope, index_id.wrapping_add(1), &foreign_vector),
                row_value(&foreign_vector),
            )
            .unwrap();
        transaction
            .put(
                row_key(
                    DataScope::Tenant(TenantId::from_u128(0xBEEF)),
                    index_id,
                    &foreign_vector,
                ),
                row_value(&foreign_vector),
            )
            .unwrap();
        transaction.commit().await.unwrap();

        Self {
            db,
            scope,
            index_id,
            node_count,
            rows,
        }
    }

    fn store(&self) -> VectorMemoryStore {
        VectorMemoryStore::new(self.scope, self.index_id, u64::MAX)
    }

    async fn load(
        &self,
        budget: VectorMemoryAdmissionBudget,
    ) -> (VectorMemoryStore, VectorMemoryStoreLoadSummary) {
        let store = self.store();
        let summary = store
            .load_descriptor_bound_with_budget(&self.db, budget, None)
            .await
            .expect("fixture hydration succeeds");
        (store, summary)
    }

    /// Model containing exactly the first `admitted` rows in scan order.
    fn prefix_model(&self, admitted: usize) -> Model {
        let mut model = Model::default();
        for row in &self.rows[..admitted] {
            model.admit(row);
        }
        model
    }
}

/// Unbounded hydration returns byte-identical rows for every kind and layer,
/// skips foreign and layer-0 rows, and charges what it reports.
#[tokio::test]
async fn unbounded_hydration_returns_every_row_byte_for_byte() {
    let fixture = HydrationFixture::build("store_oracle_unbounded", 2_048).await;
    let (store, summary) = fixture.load(VectorMemoryAdmissionBudget::Unbounded).await;

    assert_eq!(summary.loaded_entries, fixture.rows.len());
    assert_eq!(
        summary.completion,
        VectorMemoryStoreLoadCompletion::Complete
    );
    assert_eq!(store.estimated_bytes(), summary.estimated_bytes);
    let total_value_bytes: usize = fixture.rows.iter().map(|row| row_value(row).len()).sum();
    assert!(
        summary.estimated_bytes >= u64::try_from(total_value_bytes).unwrap(),
        "the charge covers at least every admitted value byte"
    );
    fixture
        .prefix_model(fixture.rows.len())
        .assert_matches(&store, 0..fixture.node_count + 1);
}

/// Every bounded hydration admits an exact scan-order prefix and never charges
/// more than its budget; a budget of the unbounded charge admits every row.
#[tokio::test]
async fn bounded_hydration_admits_an_exact_scan_prefix_within_budget() {
    let fixture = HydrationFixture::build("store_oracle_bounded", 1_024).await;
    let (_, full) = fixture.load(VectorMemoryAdmissionBudget::Unbounded).await;

    let generous = full.estimated_bytes * 4 + 8 * 1024 * 1024;
    let budgets = [
        0,
        1,
        63,
        64,
        4_096,
        65_536,
        full.estimated_bytes / 3,
        full.estimated_bytes / 2,
        full.estimated_bytes - 1,
        full.estimated_bytes,
        generous,
    ];
    for budget in budgets {
        let (store, summary) = fixture
            .load(VectorMemoryAdmissionBudget::Bounded(budget))
            .await;
        assert!(
            summary.estimated_bytes <= budget,
            "budget {budget} charged {}",
            summary.estimated_bytes
        );
        assert_eq!(store.estimated_bytes(), summary.estimated_bytes);
        let expected_completion = if summary.loaded_entries == fixture.rows.len() {
            VectorMemoryStoreLoadCompletion::Complete
        } else {
            VectorMemoryStoreLoadCompletion::BudgetExhausted
        };
        assert_eq!(summary.completion, expected_completion, "budget {budget}");
        if budget == 0 {
            assert_eq!(summary.loaded_entries, 0);
        }
        if budget >= full.estimated_bytes {
            assert_eq!(
                summary.loaded_entries,
                fixture.rows.len(),
                "budget {budget}"
            );
            assert_eq!(summary.estimated_bytes, full.estimated_bytes);
        }
        fixture
            .prefix_model(summary.loaded_entries)
            .assert_matches(&store, 0..fixture.node_count);
    }
}

/// Commit eviction after hydration removes exactly the named rows.
#[tokio::test]
async fn removal_after_hydration_matches_the_model() {
    let fixture = HydrationFixture::build("store_oracle_removal", 1_024).await;
    let (store, _) = fixture.load(VectorMemoryAdmissionBudget::Unbounded).await;
    let mut model = fixture.prefix_model(fixture.rows.len());
    let estimated = store.estimated_bytes();

    for node_id in (0..fixture.node_count).step_by(24) {
        store.remove_node(node_id);
        model.remove_node(node_id);
    }
    for node_id in (0..fixture.node_count).step_by(40) {
        store.remove_upper_neighbors(1, node_id);
        model.neighbors.remove(&(1, node_id));
    }
    // Removing the lowest layer of a multi-layer node keeps the others.
    store.remove_upper_neighbors(2, 512);
    model.neighbors.remove(&(2, 512));
    store.remove_upper_vector(64);
    model.vectors.remove(&64);
    store.remove_simhash(3);
    model.simhashes.remove(&3);
    // Removing every neighbor layer keeps the node's vector.
    for layer in 0..=MAX_LAYER {
        store.remove_upper_neighbors(layer, 1_000);
    }
    model.neighbors.retain(|(_, node), _| *node != 1_000);
    model.assert_matches(&store, 0..fixture.node_count);

    assert_eq!(
        store.estimated_bytes(),
        estimated,
        "evicted rows stay charged until the store is replaced"
    );

    store.clear();
    assert_eq!(store.estimated_bytes(), 0);
    Model::default().assert_matches(&store, 0..fixture.node_count);
}

/// Returned rows stay valid after removal, clear, and dropping the store.
#[tokio::test]
async fn returned_rows_outlive_removal_clear_and_the_store() {
    let fixture = HydrationFixture::build("store_oracle_lifetime", 256).await;
    let (store, _) = fixture.load(VectorMemoryAdmissionBudget::Unbounded).await;
    let model = fixture.prefix_model(fixture.rows.len());

    let vector = store.get_upper_vector(8).expect("large vector cached");
    let neighbors = store
        .get_upper_neighbors_bytes(1, 64)
        .expect("neighbors cached");
    store.remove_node(8);
    store.clear();
    drop(store);

    assert_eq!(Some(&vector), model.vectors.get(&8));
    assert_eq!(Some(&neighbors), model.neighbors.get(&(1, 64)));
}

/// Concurrent lookups during removal and clear only ever see the hydrated
/// bytes or a miss, and a removed row never reappears.
#[test]
fn concurrent_lookups_during_removal_see_hydrated_bytes_or_miss() {
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .unwrap();
    let fixture = runtime.block_on(HydrationFixture::build("store_oracle_concurrent", 2_048));
    let (store, _) = runtime.block_on(fixture.load(VectorMemoryAdmissionBudget::Unbounded));
    let store = Arc::new(store);
    let model = Arc::new(fixture.prefix_model(fixture.rows.len()));
    let node_count = fixture.node_count;
    let done = Arc::new(AtomicBool::new(false));

    std::thread::scope(|scope| {
        for reader in 0..6u64 {
            let store = Arc::clone(&store);
            let model = Arc::clone(&model);
            let done = Arc::clone(&done);
            scope.spawn(move || {
                let mut evicted = BTreeMap::<(u8, u16, NodeId), ()>::new();
                let mut check = |kind: u8,
                                 layer: u16,
                                 node_id: NodeId,
                                 got: Option<Bytes>,
                                 expected: Option<&Bytes>| {
                    match got {
                        Some(bytes) => {
                            assert_eq!(
                                Some(&bytes),
                                expected,
                                "node {node_id} kind {kind} layer {layer}"
                            );
                            assert!(
                                !evicted.contains_key(&(kind, layer, node_id)),
                                "removed row reappeared for node {node_id}"
                            );
                        }
                        None => {
                            if expected.is_some() {
                                evicted.insert((kind, layer, node_id), ());
                            }
                        }
                    }
                };
                while !done.load(Ordering::Acquire) {
                    for offset in 0..node_count {
                        let node_id = (offset + reader * 97) % node_count;
                        check(
                            0,
                            0,
                            node_id,
                            store.get_upper_vector(node_id),
                            model.vectors.get(&node_id),
                        );
                        for layer in 1..=MAX_LAYER {
                            check(
                                1,
                                layer,
                                node_id,
                                store.get_upper_neighbors_bytes(layer, node_id),
                                model.neighbors.get(&(layer, node_id)),
                            );
                        }
                    }
                }
            });
        }
        for node_id in (0..node_count).rev() {
            store.remove_node(node_id);
            if node_id % 256 == 0 {
                std::thread::yield_now();
            }
        }
        store.clear();
        done.store(true, Ordering::Release);
    });
    Model::default().assert_matches(&store, 0..node_count);
}

/// One mutation applied to both the store and the model.
#[derive(Debug, Clone)]
enum Operation {
    InsertVector(NodeId, Vec<u8>),
    InsertNeighbors(u16, NodeId, Vec<u8>),
    InsertSimHash(NodeId, u64),
    RemoveVector(NodeId),
    RemoveNeighbors(u16, NodeId),
    RemoveNodeNeighbors(NodeId),
    RemoveSimHash(NodeId),
    RemoveNode(NodeId),
    Clear,
}

fn operation() -> impl Strategy<Value = Operation> {
    let node = 0..6u64;
    let layer = 0..=MAX_LAYER;
    let value = prop_oneof![
        8 => proptest::collection::vec(any::<u8>(), 0..48),
        1 => proptest::collection::vec(any::<u8>(), 4_000..9_000),
    ];
    prop_oneof![
        4 => (node.clone(), value.clone()).prop_map(|(n, v)| Operation::InsertVector(n, v)),
        4 => (layer.clone(), node.clone(), value).prop_map(|(l, n, v)| Operation::InsertNeighbors(l, n, v)),
        2 => (node.clone(), any::<u64>()).prop_map(|(n, b)| Operation::InsertSimHash(n, b)),
        1 => node.clone().prop_map(Operation::RemoveVector),
        2 => (layer, node.clone()).prop_map(|(l, n)| Operation::RemoveNeighbors(l, n)),
        1 => node.clone().prop_map(Operation::RemoveNodeNeighbors),
        1 => node.clone().prop_map(Operation::RemoveSimHash),
        1 => node.prop_map(Operation::RemoveNode),
        1 => Just(Operation::Clear),
    ]
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(512))]

    /// Every interleaving of upserts and removals matches a plain map model.
    #[test]
    fn mutation_sequences_match_the_model(operations in proptest::collection::vec(operation(), 1..80)) {
        let store = VectorMemoryStore::new(DataScope::LegacyUnscoped, 7, u64::MAX);
        let mut model = Model::default();
        for operation in operations {
            match operation {
                Operation::InsertVector(node_id, value) => {
                    let value = Bytes::from(value);
                    store.insert_upper_vector(node_id, value.clone());
                    model.vectors.insert(node_id, value);
                }
                Operation::InsertNeighbors(layer, node_id, value) => {
                    let value = Bytes::from(value);
                    store.insert_upper_neighbors_bytes(layer, node_id, value.clone());
                    model.neighbors.insert((layer, node_id), value);
                }
                Operation::InsertSimHash(node_id, bits) => {
                    store.insert_simhash(node_id, SimHash::from_bits(bits));
                    model.simhashes.insert(node_id, bits);
                }
                Operation::RemoveVector(node_id) => {
                    store.remove_upper_vector(node_id);
                    model.vectors.remove(&node_id);
                }
                Operation::RemoveNeighbors(layer, node_id) => {
                    store.remove_upper_neighbors(layer, node_id);
                    model.neighbors.remove(&(layer, node_id));
                }
                Operation::RemoveNodeNeighbors(node_id) => {
                    for layer in 0..=MAX_LAYER {
                        store.remove_upper_neighbors(layer, node_id);
                    }
                    model.neighbors.retain(|(_, node), _| *node != node_id);
                }
                Operation::RemoveSimHash(node_id) => {
                    store.remove_simhash(node_id);
                    model.simhashes.remove(&node_id);
                }
                Operation::RemoveNode(node_id) => {
                    store.remove_node(node_id);
                    model.remove_node(node_id);
                }
                Operation::Clear => {
                    store.clear();
                    model = Model::default();
                }
            }
            model.assert_matches(&store, 0..7);
        }
    }
}

//! Node-level vector cache contracts through the public query path.
//!
//! These scenarios open real writer and reader nodes over one process-local
//! object store, build a managed vector index through DDL, and observe the
//! traversal-scoped search counters. `simhash_row_requests` counts only rows
//! fetched from storage, so zero proves the resident cache served every
//! candidate while the returned ranking proves the answer is still fresh.
//!
//! A graph write only queues its index operations; the writer's queue
//! publisher changes physical vector rows in a later commit of its own. Every
//! writer here opens with automatic publication paused and drains its queue
//! explicitly, so each scenario decides when physical rows change: a queued
//! write fences no cached row and the search overlay serves it, and only a
//! publication commit evicts the rows it rewrote.

use std::num::NonZeroUsize;
use std::sync::Arc;
use std::time::Duration;

use helix_ast::prelude::*;

use crate::config::IndexOperationQueueTuning;
use crate::encoding::v2::values::indexes::operation_queue::QueueFamily;
use crate::index_lifecycle::queue::publication::PublicationOutcome;
use crate::index_lifecycle::{ActiveIndexHandle, VectorPhysicalLayout};
use crate::search::vector::hnsw::restricted::{observe_restricted_search, RestrictedSearchStats};
use crate::search::vector::{ValidatedVectorGenerationHandle, VectorMemoryStore};
use crate::{DatabaseSequence, HelixDB, HelixDbError, HelixDbSource, ProcessLocalDatabaseToken};

/// Scoped fixture documents; `near` is nearest the search query.
const FIXTURE: [(&str, [f32; 3]); 3] = [
    ("far", [0.0, 0.0, 1.0]),
    ("mid", [0.5, 1.0, 0.0]),
    ("near", [1.0, 0.2, 0.0]),
];

/// Opens a writer whose queued index operations wait for [`drain`].
async fn open_paused_writer(token: ProcessLocalDatabaseToken) -> HelixDB {
    let source = HelixDbSource::InMemoryToken { token };
    let config = source
        .embedded_default_config()
        .with_index_operation_queue_tuning(
            IndexOperationQueueTuning::default().with_publication_paused_for_tests(),
        );
    HelixDB::open_with_config(source, config)
        .await
        .expect("writer opens")
}

/// Creates the managed `Doc.embedding` index and waits until it is Active.
async fn create_vector_index(writer: &HelixDB, tenant_property: Option<&str>) {
    let receipts = writer
        .query(QueryRequest::write(
            write_batch()
                .var_as(
                    "vector",
                    g().create_vector_index_nodes(
                        "Doc",
                        "embedding",
                        NonZeroUsize::new(3).expect("fixture dimension is non-zero"),
                        VectorDistanceMetric::Euclidean,
                        tenant_property,
                    ),
                )
                .returning(["vector"]),
        ))
        .await
        .expect("vector index DDL is accepted");
    let operation_id = receipts["vector"]["operation_id"]
        .as_str()
        .expect("vector index DDL returns an operation")
        .to_string();
    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let status = writer
                .query(QueryRequest::read(
                    read_batch()
                        .var_as("op", g().get_index_operation(operation_id.clone()))
                        .returning(["op"]),
                ))
                .await
                .expect("vector index operation status loads")
                .to_string();
            if status.contains("succeeded") {
                break;
            }
            assert!(
                !status.contains("blocked") && !status.contains("aborted"),
                "vector index build failed: {status}"
            );
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
    })
    .await
    .expect("vector index activates");
}

/// Creates the one `Group` whose `HAS` edges scope every search.
async fn create_group(writer: &HelixDB) {
    writer
        .query(QueryRequest::write(write_batch().var_as(
            "group",
            g().add_n("Group", vec![("name", PropertyValue::from("scope"))]),
        )))
        .await
        .expect("group commits");
}

/// Adds one `Doc` reachable from the scoping `Group` and returns its ID.
async fn add_doc(writer: &HelixDB, name: &str, embedding: [f32; 3]) -> u64 {
    let result = writer
        .query(QueryRequest::write(
            write_batch()
                .var_as("group", g().n_with_label("Group"))
                .var_as(
                    "doc",
                    g().add_n(
                        "Doc",
                        vec![
                            ("name", PropertyValue::from(name)),
                            ("embedding", PropertyValue::from(embedding.to_vec())),
                        ],
                    ),
                )
                .var_as(
                    "edge",
                    g().n(NodeRef::var("group")).add_e(
                        "HAS",
                        NodeRef::var("doc"),
                        Vec::<(String, PropertyValue)>::new(),
                    ),
                )
                .returning(["doc"]),
        ))
        .await
        .expect("doc commits");
    result["doc"][0]["$id"]
        .as_u64()
        .expect("the created doc returns its ID")
}

/// Publishes the writer's vector queue until it is empty.
async fn drain(writer: &HelixDB) {
    let target = crate::index_lifecycle::queue::tests::target(writer, QueueFamily::Vector).await;
    let publisher = writer
        .index_queue_publisher()
        .expect("writer runs a queue publisher");
    for _ in 0..1_000 {
        match publisher
            .publish_once(target)
            .await
            .expect("publication succeeds")
        {
            PublicationOutcome::Empty => {
                assert_eq!(writer.index_operation_queue_stats().pending_operations, 0);
                return;
            }
            PublicationOutcome::Published { .. } | PublicationOutcome::Trimmed => {}
            outcome @ (PublicationOutcome::Discarded { .. }
            | PublicationOutcome::Deferred
            | PublicationOutcome::Retry
            | PublicationOutcome::Blocked
            | PublicationOutcome::Stalled) => panic!("publication stalled: {outcome:?}"),
        }
    }
    panic!("publication did not drain the vector queue");
}

/// Runs one traversal-scoped vector search and returns ranked names with its counters.
async fn scoped_search(db: &HelixDB) -> (Vec<String>, RestrictedSearchStats) {
    let request = QueryRequest::read(
        read_batch()
            .var_as(
                "r",
                g().n_with_label("Group")
                    .out(Some("HAS"))
                    .vector_search("Doc", "embedding", vec![1.0, 0.0, 0.0], 3, None)
                    .project(vec![PropertyProjection::new("name")]),
            )
            .returning(["r"]),
    );
    let (result, stats) = observe_restricted_search(Box::pin(db.query(request))).await;
    let names = result.expect("scoped vector search succeeds")["r"]
        .as_array()
        .expect("scoped vector search returns rows")
        .iter()
        .map(|row| {
            row["name"]
                .as_str()
                .expect("every doc projects its name")
                .to_string()
        })
        .collect();
    (
        names,
        stats.expect("scoped vector search records restricted counters"),
    )
}

/// Runs one unrestricted vector search and returns ranked names.
async fn unrestricted_search(db: &HelixDB) -> Vec<String> {
    let request = QueryRequest::read(
        read_batch()
            .var_as(
                "r",
                g().vector_search_nodes("Doc", "embedding", vec![1.0, 0.0, 0.0], 3, None)
                    .project(vec![PropertyProjection::new("name")]),
            )
            .returning(["r"]),
    );
    Box::pin(db.query(request))
        .await
        .expect("unrestricted vector search succeeds")["r"]
        .as_array()
        .expect("unrestricted vector search returns rows")
        .iter()
        .map(|row| {
            row["name"]
                .as_str()
                .expect("every doc projects its name")
                .to_string()
        })
        .collect()
}

/// Repeats `scoped_search` until `done` accepts its outcome.
async fn search_until(
    db: &HelixDB,
    done: impl Fn(&[String], &RestrictedSearchStats) -> bool,
) -> (Vec<String>, RestrictedSearchStats) {
    tokio::time::timeout(Duration::from_secs(30), async {
        loop {
            let (names, stats) = scoped_search(db).await;
            if done(&names, &stats) {
                return (names, stats);
            }
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
    })
    .await
    .expect("scoped vector search reaches the expected state")
}

/// Stops the background refresh loop so a scenario controls every refresh.
async fn stop_background_refresh(db: &HelixDB) {
    db.inner
        .caches
        .vector_memory
        .refresh_task
        .lock()
        .await
        .take()
        .expect("the node owns a vector refresh task")
        .stop()
        .await;
}

/// Runs one manual refresh, retrying only a reader poller race.
async fn refresh_until_published(db: &HelixDB) {
    tokio::time::timeout(Duration::from_secs(10), async {
        loop {
            match db.refresh_vector_memory_cache().await {
                Ok(()) => break,
                Err(HelixDbError::RequestReadViewChanged) => {
                    tokio::time::sleep(Duration::from_millis(10)).await;
                }
                Err(error) => panic!("vector cache refresh failed: {error}"),
            }
        }
    })
    .await
    .expect("vector cache refresh completes");
}

/// Waits until `reader` applied at least `sequence`.
async fn wait_until_applied(reader: &HelixDB, sequence: DatabaseSequence) {
    tokio::time::timeout(Duration::from_secs(30), async {
        while reader
            .visible_sequence()
            .await
            .expect("reader sequence loads")
            < sequence
        {
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
    })
    .await
    .expect("reader applies the flushed writer state");
}

/// Flushes the writer and waits until `reader` applied everything it flushed.
async fn publish_to_reader(writer: &HelixDB, reader: &HelixDB) {
    let flushed = writer.flush_writer().await.expect("writer flushes");
    wait_until_applied(reader, flushed).await;
}

/// Returns the node's only Active vector generation.
fn active_vector(db: &HelixDB) -> ActiveIndexHandle {
    db.active_index_handles_loaded(crate::encoding::keys::scope::DataScope::LegacyUnscoped)
        .into_iter()
        .find(|handle| matches!(handle, ActiveIndexHandle::Vector { .. }))
        .expect("the fixture owns one Active vector generation")
}

/// Returns the validated handle of the node's unpartitioned vector generation.
fn unpartitioned_generation(db: &HelixDB) -> ValidatedVectorGenerationHandle {
    let active = active_vector(db);
    let ActiveIndexHandle::Vector {
        layout: VectorPhysicalLayout::Unpartitioned { physical_index_id },
        ..
    } = &active
    else {
        panic!("the fixture vector index is unpartitioned");
    };
    ValidatedVectorGenerationHandle::try_from_active_current(&active, *physical_index_id)
        .expect("the Active generation validates")
}

/// Returns the resident store of the node's only Active vector generation.
fn resident_store(db: &HelixDB) -> Arc<VectorMemoryStore> {
    Arc::clone(
        db.vector_cache_registry()
            .resident_guard_for(&unpartitioned_generation(db))
            .expect("the Active generation is hydrated")
            .store(),
    )
}

/// Returns the store a request at the node's latest snapshot attaches, if any.
async fn attached_store(
    db: &HelixDB,
    generation: &ValidatedVectorGenerationHandle,
) -> Option<Arc<VectorMemoryStore>> {
    let sequence = db
        .visible_sequence()
        .await
        .expect("node sequence loads")
        .get();
    db.vector_cache_registry()
        .read_guard_for(generation, sequence)
        .ok()
        .map(|guard| Arc::clone(guard.store()))
}

#[tokio::test]
async fn writer_cache_stays_attached_across_commits_and_evicts_only_vector_rows() {
    let writer =
        open_paused_writer(ProcessLocalDatabaseToken::new("writer-vector-cache").unwrap()).await;
    create_vector_index(&writer, None).await;
    create_group(&writer).await;
    for (name, embedding) in FIXTURE {
        add_doc(&writer, name, embedding).await;
    }
    drain(&writer).await;
    stop_background_refresh(&writer).await;
    refresh_until_published(&writer).await;
    let hydrated = resident_store(&writer);
    let (names, stats) = scoped_search(&writer).await;
    assert_eq!(names, ["near", "mid", "far"]);
    assert_eq!(stats.simhash_row_requests, 0);

    // A commit that touches no vector row advances the snapshot but keeps the
    // store attached, and the next refresh retains it without rescanning.
    writer
        .query(QueryRequest::write(write_batch().var_as(
            "unrelated",
            g().add_n("Unrelated", vec![("name", PropertyValue::from("other"))]),
        )))
        .await
        .expect("unrelated write commits");
    let (names, stats) = scoped_search(&writer).await;
    assert_eq!(names, ["near", "mid", "far"]);
    assert_eq!(
        stats.simhash_row_requests, 0,
        "a newer writer snapshot still attaches the commit-fenced store"
    );
    refresh_until_published(&writer).await;
    assert!(Arc::ptr_eq(&hydrated, &resident_store(&writer)));

    // A queued vector write fences no cached row: the overlay serves the
    // pending doc beside cached rows, and the next refresh keeps the store.
    add_doc(&writer, "nearest", [1.0, 0.0, 0.0]).await;
    assert_eq!(writer.index_operation_queue_stats().pending_operations, 1);
    let (names, stats) = scoped_search(&writer).await;
    assert_eq!(names, ["nearest", "near", "mid"]);
    assert_eq!(
        stats.simhash_row_requests, 0,
        "a queued write leaves every cached row attached"
    );
    refresh_until_published(&writer).await;
    assert!(
        Arc::ptr_eq(&hydrated, &resident_store(&writer)),
        "a queued write forces no rescan"
    );

    // A publication commit evicts only its dirty rows; the store stays
    // attached and the new row falls back to storage until the next refresh.
    drain(&writer).await;
    let (names, stats) = scoped_search(&writer).await;
    assert_eq!(names, ["nearest", "near", "mid"]);
    assert!(
        (1..4).contains(&stats.simhash_row_requests),
        "only rows the publication changed are read from storage, got {}",
        stats.simhash_row_requests
    );
    let attached = attached_store(&writer, &unpartitioned_generation(&writer))
        .await
        .expect("the publication commit keeps the store attachable");
    assert!(Arc::ptr_eq(&hydrated, &attached));
    drop(attached);
    refresh_until_published(&writer).await;
    assert!(
        !Arc::ptr_eq(&hydrated, &resident_store(&writer)),
        "a resolved publication commit forces a rescan that caches its rows"
    );
    let (names, stats) = scoped_search(&writer).await;
    assert_eq!(names, ["nearest", "near", "mid"]);
    assert_eq!(stats.simhash_row_requests, 0);

    writer.close().await.expect("writer closes");
}

#[tokio::test]
async fn writer_cache_overlays_queued_updates_and_deletes_until_publication() {
    let writer = open_paused_writer(
        ProcessLocalDatabaseToken::new("writer-vector-cache-update-delete").unwrap(),
    )
    .await;
    create_vector_index(&writer, None).await;
    create_group(&writer).await;
    let mut ids = Vec::new();
    for (name, embedding) in FIXTURE {
        ids.push(add_doc(&writer, name, embedding).await);
    }
    add_doc(&writer, "other", [0.0, 1.0, 1.0]).await;
    let [far, _, near] = ids[..] else {
        unreachable!("the fixture adds three docs")
    };
    drain(&writer).await;
    stop_background_refresh(&writer).await;
    refresh_until_published(&writer).await;
    let generation = unpartitioned_generation(&writer);
    let hydrated = resident_store(&writer);
    let (names, stats) = scoped_search(&writer).await;
    assert_eq!(names, ["near", "mid", "far"]);
    assert_eq!(stats.simhash_row_requests, 0);
    assert_eq!(unrestricted_search(&writer).await, ["near", "mid", "far"]);

    // Re-embed `far` onto the query and delete `near`; both stay queued.
    writer
        .query(QueryRequest::write(
            write_batch().var_as(
                "updated",
                g().n(NodeRef::from(far))
                    .set_property("embedding", vec![1.0_f32, 0.0, 0.0]),
            ),
        ))
        .await
        .expect("update commits");
    writer
        .query(QueryRequest::write(
            write_batch().var_as("dropped", g().n(NodeRef::from(near)).drop()),
        ))
        .await
        .expect("delete commits");
    assert_eq!(writer.index_operation_queue_stats().pending_operations, 2);

    // `far`'s cached physical row is superseded: the restricted search drops
    // it from its candidates and ranks the pending vector first, while every
    // other candidate is still served from the cache.
    let (names, stats) = scoped_search(&writer).await;
    assert_eq!(names, ["far", "mid", "other"]);
    assert_eq!(stats.simhash_row_requests, 0);
    // The unrestricted search suppresses both superseded physical rows and
    // widens past them through the attached store.
    assert_eq!(unrestricted_search(&writer).await, ["far", "mid", "other"]);
    let attached = attached_store(&writer, &generation)
        .await
        .expect("queued writes keep the store attachable");
    assert!(Arc::ptr_eq(&hydrated, &attached));
    drop(attached);
    refresh_until_published(&writer).await;
    assert!(
        Arc::ptr_eq(&hydrated, &resident_store(&writer)),
        "queued writes force no rescan"
    );

    // Publication rewrites `far` and removes `near`: only their rows leave
    // the attached store, `far` returns with its new vector, and the deleted
    // doc never reappears.
    drain(&writer).await;
    let (names, stats) = scoped_search(&writer).await;
    assert_eq!(names, ["far", "mid", "other"]);
    assert!(
        (1..3).contains(&stats.simhash_row_requests),
        "only the rewritten row is read from storage, got {}",
        stats.simhash_row_requests
    );
    assert_eq!(unrestricted_search(&writer).await, ["far", "mid", "other"]);
    let attached = attached_store(&writer, &generation)
        .await
        .expect("the publication commit keeps the store attachable");
    assert!(Arc::ptr_eq(&hydrated, &attached));
    drop(attached);
    refresh_until_published(&writer).await;
    assert!(!Arc::ptr_eq(&hydrated, &resident_store(&writer)));
    let (names, stats) = scoped_search(&writer).await;
    assert_eq!(names, ["far", "mid", "other"]);
    assert_eq!(stats.simhash_row_requests, 0);
    assert_eq!(unrestricted_search(&writer).await, ["far", "mid", "other"]);

    writer.close().await.expect("writer closes");
}

#[tokio::test]
async fn eventual_search_past_the_suppression_limit_matches_a_search_without_the_cache() {
    /// Returns `(id, distance)` of the `k` docs nearest `query`.
    async fn nearest(
        db: &HelixDB,
        query: [f32; 3],
        k: usize,
        consistency: SearchConsistency,
    ) -> crate::error::Result<Vec<(u64, f64)>> {
        let request = QueryRequest::read(
            read_batch()
                .var_as(
                    "hits",
                    g().vector_search_nodes("Doc", "embedding", query.to_vec(), k, None),
                )
                .returning(["hits"]),
        )
        .with_search_consistency(consistency)
        .expect("read requests accept either consistency");
        Ok(Box::pin(db.query(request)).await?["hits"]
            .as_array()
            .expect("vector search returns hits")
            .iter()
            .map(|hit| {
                (
                    hit["$id"].as_u64().expect("every hit has an ID"),
                    hit["$distance"].as_f64().expect("every hit has a distance"),
                )
            })
            .collect())
    }

    let writer =
        open_paused_writer(ProcessLocalDatabaseToken::new("writer-vector-cache-eventual").unwrap())
            .await;
    create_vector_index(&writer, None).await;
    // 802 docs on a line, written in batches of 100.
    let mut ids = Vec::with_capacity(802);
    for start in (0..802_u16).step_by(100) {
        let positions = start..(start + 100).min(802);
        let batch = positions.clone().fold(write_batch(), |batch, position| {
            batch.var_as(
                &format!("d{position}"),
                g().add_n(
                    "Doc",
                    vec![(
                        "embedding",
                        PropertyValue::from(vec![f32::from(position), 0.0, 0.0]),
                    )],
                ),
            )
        });
        let result = writer
            .query(QueryRequest::write(batch.returning(
                positions.clone().map(|position| format!("d{position}")),
            )))
            .await
            .expect("docs commit");
        ids.extend(positions.map(|position| {
            result[format!("d{position}")][0]["$id"]
                .as_u64()
                .expect("every created doc returns its ID")
        }));
    }
    drain(&writer).await;
    stop_background_refresh(&writer).await;
    refresh_until_published(&writer).await;
    let generation = unpartitioned_generation(&writer);
    let hydrated = resident_store(&writer);

    // 801 queued rewrites move the docs nearest the origin far away, so each
    // one's published result lies ahead of the answer.
    for start in (0..801_u16).step_by(100) {
        let batch = (start..(start + 100).min(801)).fold(write_batch(), |batch, position| {
            batch.var_as(
                &format!("d{position}"),
                g().n(NodeRef::from(ids[usize::from(position)]))
                    .set_property("embedding", vec![10_000.0 + f32::from(position), 0.0, 0.0]),
            )
        });
        writer
            .query(QueryRequest::write(batch))
            .await
            .expect("rewrites commit");
    }
    assert_eq!(writer.index_operation_queue_stats().pending_operations, 801);

    let error = nearest(&writer, [0.0; 3], 1, SearchConsistency::Strong)
        .await
        .expect_err("strong search never skips the limit's worth of superseded results");
    assert!(error.is_index_backpressure(), "unexpected error: {error}");
    // Eventual search overlays the oldest 800 rewrites and serves the newest
    // from its published row, through the attached store. Searches that need
    // no widening still overlay every rewrite.
    let queries = [
        ([0.0, 0.0, 0.0], 1),
        ([10_800.0, 0.0, 0.0], 1),
        ([10_000.0, 0.0, 0.0], 3),
    ];
    let mut cached = Vec::new();
    for (query, k) in queries {
        cached.push(
            nearest(&writer, query, k, SearchConsistency::Eventual)
                .await
                .expect("eventual search degrades instead of failing"),
        );
    }
    assert_eq!(cached[0], [(ids[800], 640_000.0)]);
    assert_eq!(cached[1], [(ids[800], 0.0)]);
    assert_eq!(
        cached[2].iter().map(|(id, _)| *id).collect::<Vec<_>>(),
        ids[..3]
    );
    let attached = attached_store(&writer, &generation)
        .await
        .expect("queued rewrites keep the store attachable");
    assert!(Arc::ptr_eq(&hydrated, &attached));
    drop(attached);

    // Without the cache, every search reads storage and answers the same.
    writer.vector_cache_registry().retire(&generation).await;
    assert!(attached_store(&writer, &generation).await.is_none());
    for ((query, k), cached) in queries.into_iter().zip(cached) {
        assert_eq!(
            nearest(&writer, query, k, SearchConsistency::Eventual)
                .await
                .expect("eventual search degrades instead of failing"),
            cached,
            "{query:?}"
        );
    }

    writer.close().await.expect("writer closes");
}

#[tokio::test]
async fn reader_cache_serves_scoped_search_and_follows_publication_commits() {
    let token = ProcessLocalDatabaseToken::new("reader-vector-cache").unwrap();
    let writer = open_paused_writer(token.clone()).await;
    create_vector_index(&writer, None).await;
    create_group(&writer).await;
    for (name, embedding) in FIXTURE {
        add_doc(&writer, name, embedding).await;
    }
    drain(&writer).await;
    let published = writer.flush_writer().await.expect("writer flushes");

    let reader = HelixDB::open_reader(HelixDbSource::InMemoryToken { token })
        .await
        .expect("reader opens");
    reader.wait_for_startup_cache_warm().await;
    wait_until_applied(&reader, published).await;
    let (names, _) = search_until(&reader, |_, stats| stats.simhash_row_requests == 0).await;
    assert_eq!(names, ["near", "mid", "far"]);

    // The background loop republishes after the reader applies the
    // publication commit.
    add_doc(&writer, "nearest", [1.0, 0.0, 0.0]).await;
    drain(&writer).await;
    publish_to_reader(&writer, &reader).await;
    let (names, _) = search_until(&reader, |names, stats| {
        names.first().map(String::as_str) == Some("nearest") && stats.simhash_row_requests == 0
    })
    .await;
    assert_eq!(names, ["nearest", "near", "mid"]);

    // Without a refresh, a newer reader sequence falls back to storage while
    // the overlay serves the queued doc.
    stop_background_refresh(&reader).await;
    add_doc(&writer, "second", [1.0, 0.1, 0.0]).await;
    publish_to_reader(&writer, &reader).await;
    let (names, stats) = scoped_search(&reader).await;
    assert_eq!(names, ["nearest", "second", "near"]);
    assert!(
        stats.simhash_row_requests > 0,
        "an exact-sequence store is never attached to a newer reader snapshot"
    );
    // A store hydrated at the queued write's sequence serves every published
    // row, and the overlay still supplies the queued doc.
    refresh_until_published(&reader).await;
    let (names, stats) = scoped_search(&reader).await;
    assert_eq!(names, ["nearest", "second", "near"]);
    assert_eq!(stats.simhash_row_requests, 0);

    // The publication commit advances the reader past that store: it falls
    // back to storage with the same answer until the next refresh.
    drain(&writer).await;
    publish_to_reader(&writer, &reader).await;
    let (names, stats) = scoped_search(&reader).await;
    assert_eq!(names, ["nearest", "second", "near"]);
    assert!(
        stats.simhash_row_requests > 0,
        "a publication commit leaves the reader store behind its snapshot"
    );
    refresh_until_published(&reader).await;
    let (names, stats) = scoped_search(&reader).await;
    assert_eq!(names, ["nearest", "second", "near"]);
    assert_eq!(stats.simhash_row_requests, 0);

    reader.close().await.expect("reader closes");
    writer.close().await.expect("writer closes");
}

#[tokio::test]
async fn publication_that_reclaims_a_partition_retires_its_cache_store() {
    /// Returns the handle of the generation's only mapped tenant partition
    /// and its mapping row.
    async fn only_partition(
        db: &HelixDB,
    ) -> (ValidatedVectorGenerationHandle, bytes::Bytes, bytes::Bytes) {
        use crate::encoding::v2::keys::{ManagedIndexKey, RecordKind, ScopedKey};

        let active = active_vector(db);
        let ActiveIndexHandle::Vector {
            scope,
            index_id,
            generation,
            layout: VectorPhysicalLayout::Partitioned,
            ..
        } = &active
        else {
            panic!("the fixture vector index is partitioned");
        };
        let prefix = ManagedIndexKey::data_prefix(
            *scope,
            ScopedKey::generation_prefix(
                RecordKind::VectorPartitionMapping,
                *index_id,
                *generation,
            ),
        );
        let storage = db.inner_db();
        let mut rows = storage
            .scan_prefix(&prefix, ..)
            .await
            .expect("partition mappings scan");
        let row = rows
            .next()
            .await
            .expect("partition mapping loads")
            .expect("one tenant partition is mapped");
        assert!(
            rows.next()
                .await
                .expect("partition mappings scan")
                .is_none(),
            "only one tenant partition is mapped"
        );
        let mapping = crate::encoding::v2::values::decode_partition_mapping(&row.value)
            .expect("partition mapping decodes");
        let handle = ValidatedVectorGenerationHandle::try_from_active_current(
            &active,
            mapping.physical_index_id,
        )
        .expect("the partition generation validates");
        (handle, row.key, row.value)
    }

    /// Asserts the source store is still resident, still caches the doc's
    /// row, and is attachable.
    async fn assert_resident(
        db: &HelixDB,
        source: &ValidatedVectorGenerationHandle,
        store: &Arc<VectorMemoryStore>,
        id: u64,
    ) {
        let resident = db
            .vector_cache_registry()
            .resident_guard_for(source)
            .expect("the source store stays resident");
        assert!(Arc::ptr_eq(store, resident.store()));
        drop(resident);
        // The HNSW node ID is the entity ID.
        assert!(
            store.get_simhash(id).is_some(),
            "the doc's row stays cached"
        );
        let attached = attached_store(db, source)
            .await
            .expect("the source store stays attachable");
        assert!(Arc::ptr_eq(store, &attached));
    }

    let writer = open_paused_writer(
        ProcessLocalDatabaseToken::new("writer-vector-cache-partition-retirement").unwrap(),
    )
    .await;
    create_vector_index(&writer, Some("tenant")).await;
    let result = writer
        .query(QueryRequest::write(
            write_batch()
                .var_as(
                    "doc",
                    g().add_n(
                        "Doc",
                        vec![
                            ("embedding", PropertyValue::from(vec![1.0_f32, 0.0, 0.0])),
                            ("tenant", PropertyValue::from("a")),
                        ],
                    ),
                )
                .returning(["doc"]),
        ))
        .await
        .expect("doc commits");
    let id = result["doc"][0]["$id"]
        .as_u64()
        .expect("the created doc returns its ID");
    drain(&writer).await;
    stop_background_refresh(&writer).await;
    refresh_until_published(&writer).await;
    let (source, mapping_key, mapping_value) = only_partition(&writer).await;
    let store = Arc::clone(
        writer
            .vector_cache_registry()
            .resident_guard_for(&source)
            .expect("the tenant partition is hydrated")
            .store(),
    );

    // Moving the partition's only doc to another tenant stays queued.
    writer
        .query(QueryRequest::write(
            write_batch().var_as(
                "moved",
                g().n(NodeRef::from(id))
                    .set_property("tenant", "b".to_string()),
            ),
        ))
        .await
        .expect("tenant move commits");
    assert_resident(&writer, &source, &store, id).await;

    let target = crate::index_lifecycle::queue::tests::target(&writer, QueueFamily::Vector).await;
    let publisher = writer
        .index_queue_publisher()
        .expect("writer runs a queue publisher");
    // A publication that fails before its commit discards the retirement.
    publisher
        .hooks()
        .fail_before_commit
        .store(true, std::sync::atomic::Ordering::SeqCst);
    assert_eq!(
        publisher.publish_once(target).await.unwrap(),
        PublicationOutcome::Retry
    );
    assert_resident(&writer, &source, &store, id).await;

    // A publication that loses a commit conflict on the reclaimed mapping
    // discards the retirement, so the source store stays resident and
    // attachable. The source is retired rather than fenced, so this does not
    // cover fence release on a conflict.
    let (reached_tx, reached) = tokio::sync::oneshot::channel();
    let (release, release_rx) = tokio::sync::oneshot::channel();
    *publisher.hooks().before_commit.lock() = Some((reached_tx, release_rx));
    let conflicts = publisher
        .metrics()
        .commit_conflicts
        .load(std::sync::atomic::Ordering::Relaxed);
    let (outcome, ()) = tokio::join!(publisher.publish_once(target), async {
        reached.await.expect("the publication stages its effects");
        let competing = writer
            .inner_db()
            .begin(slatedb::IsolationLevel::Snapshot)
            .await
            .unwrap();
        competing.put(&mapping_key, mapping_value).unwrap();
        competing.commit().await.unwrap();
        release.send(()).expect("the publication waits to commit");
    });
    assert_eq!(outcome.unwrap(), PublicationOutcome::Retry);
    assert_eq!(
        publisher
            .metrics()
            .commit_conflicts
            .load(std::sync::atomic::Ordering::Relaxed),
        conflicts + 1,
        "the competing mapping write aborts the publication"
    );
    assert_resident(&writer, &source, &store, id).await;

    // A committed publication reclaims the emptied partition and retires its
    // store, then forgets the tombstone so the identity can hydrate again.
    drain(&writer).await;
    assert!(writer
        .vector_cache_registry()
        .resident_guard_for(&source)
        .is_err());
    assert_eq!(store.estimated_bytes(), 0, "retirement clears the store");
    assert!(
        store.get_simhash(id).is_none(),
        "retirement drops the doc's row"
    );
    let (destination, _, _) = only_partition(&writer).await;
    assert_ne!(
        destination.physical_index_id(),
        source.physical_index_id(),
        "only the destination tenant stays mapped"
    );
    let (_, owns_hydration) = writer.vector_cache_registry().entry_for(&source);
    assert!(
        owns_hydration,
        "the committed retirement forgets its tombstone"
    );

    writer.close().await.expect("writer closes");
}

//! Production contracts for the retained vector build planning cache.
//!
//! This feature-gated child of the vector lifecycle driver exercises the
//! driver-owned [`VectorBuildCache`] against canonical operation and index
//! records written by the production lifecycle entry points. The sessions it
//! retains hold only fixture SimHashes that mark reuse, so no vector row
//! family is written. The budget contracts then bound retained build and
//! publication sessions in count, trim them to their max-min fair share off
//! the executor, and shrink checked-out sessions to their rebound share.

use std::num::NonZeroU64;

use slatedb::object_store::memory::InMemory;

use super::*;
use crate::config::VectorIndexDefinition;
use crate::encoding::v2::keys::NodePropertyKey;
use crate::index_lifecycle::lifecycle::{create_index_operation, InitialBuildProgress};
use crate::index_lifecycle::{IndexDdlReceipt, IndexScopeGates};
use crate::migrations::startup::bootstrap_writer;

type Euclidean = vector::distance::Euclidean;

/// Creates one vector build and returns its canonical operation and index records.
async fn create_build(
    db: &Db,
    scope: DataScope,
    property: &str,
) -> (IndexOperationRecord, IndexRecordV2) {
    let definition = ValidatedDynamicIndexDefinition::Vector(
        ValidatedVectorIndexDefinition::try_from_runtime(
            &VectorIndexDefinition::new_node(
                "Document",
                property,
                3,
                VectorDistanceMetric::Euclidean,
            )
            .expect("contract vector definition validates"),
        )
        .expect("contract V2 vector definition validates"),
    );
    let upper_bound = IndexCursor::try_new(
        DataKey::Data {
            scope,
            kind: DataKeyKind::NodeProperty(NodePropertyKey::new(1)),
        }
        .to_bytes(),
    )
    .expect("source key is a valid cursor");
    let IndexDdlReceipt::Accepted { operation_id, .. } = create_index_operation(
        db,
        scope,
        definition.clone(),
        helix_planner::ir::IndexCreateMode::ErrorIfExists,
        InitialBuildProgress::vector(upper_bound),
    )
    .await
    .expect("contract vector build is enqueued") else {
        panic!("a new vector definition enqueues a build");
    };
    let operation = crate::encoding::v2::values::decode_operation_record(
        &db.get(crate::index_lifecycle::outbox::scoped_operation_key(
            scope,
            operation_id,
        ))
        .await
        .expect("contract operation is readable")
        .expect("contract operation exists"),
    )
    .expect("contract operation decodes");
    let record = decode_index_record(
        &db.get(scoped_index_key(
            scope,
            ScopedKey::index_record(definition.identity()),
        ))
        .await
        .expect("contract index record is readable")
        .expect("contract index record exists"),
    )
    .expect("contract index record decodes");
    (operation, record)
}

/// Checks out `checkpoint`'s session and returns the SimHashes it retains.
async fn checked_out_simhashes<D: Distance>(
    cache: &VectorBuildCache,
    checkpoint: &VectorBuildCheckpoint,
) -> usize {
    cache.checkout::<D>(checkpoint).await.simhash_count()
}

/// Proves the retained cache reuses only the exact committed checkpoint.
///
/// A session is released to the next step only for the operation, index
/// revision, and progress it was committed at, and only for its own metric.
/// Another operation's step or commit leaves it in place, a stale checkpoint
/// or a committed step without state forgets it, and each operation keeps its
/// own session. Only a step progressing to another Scan offers a session.
/// The committed state crosses the outbox boundary with a diagnostic that
/// names it without exposing its rows, and source-scan planning and storage
/// errors return from the step without offering a session.
pub(crate) async fn run() {
    let db = Db::builder(
        "vector-build-cache-production-contracts",
        Arc::new(InMemory::new()),
    )
    .build()
    .await
    .expect("contract database opens");
    bootstrap_writer(&db)
        .await
        .expect("contract database bootstraps");
    let scope = DataScope::LegacyUnscoped;
    let (first, first_record) = create_build(&db, scope, "embedding").await;
    let (second, second_record) = create_build(&db, scope, "other_embedding").await;
    let checkpoint = VectorBuildCheckpoint::new(&first, &first_record, first.progress().clone());
    let other_operation =
        VectorBuildCheckpoint::new(&second, &second_record, second.progress().clone());
    let source_cursor = |entity_id| {
        IndexCursor::try_new(
            DataKey::Data {
                scope,
                kind: DataKeyKind::NodeProperty(NodePropertyKey::new(entity_id)),
            }
            .to_bytes(),
        )
        .expect("source key is a valid cursor")
    };
    let mut advanced = checkpoint.clone();
    advanced.progress = IndexOperationProgress::VectorBuild(VectorBuildProgress::Constructing(
        VectorBuildStage::Scan(SourceScanProgress {
            inclusive_upper_bound: source_cursor(1),
            cursor: Some(source_cursor(1)),
            counters: OperationCounters::default(),
        }),
    ));
    assert_ne!(advanced.progress, checkpoint.progress);

    const BUDGET: u64 = 1 << 20;
    const MARKED: usize = 3;
    let cache = VectorBuildCache::new(NonZeroU64::new(BUDGET).expect("budget is positive"));
    let marked = |checkpoint: &VectorBuildCheckpoint| {
        Some(CommittedStepState::VectorBuild(Box::new(
            OfferedVectorBuild::for_tests(
                &cache,
                VectorPlanningCheckpoint::Build(checkpoint.clone()),
                Box::new(VectorBuildSession::<Euclidean>::with_test_simhashes(
                    NonZeroU64::new(BUDGET).expect("marker budget is positive"),
                    u64::try_from(MARKED).expect("marker count fits u64"),
                )),
            ),
        )))
    };
    let retained_checkpoints = || {
        cache
            .retained
            .try_lock()
            .expect("no commit is trimming the retained sessions")
            .iter()
            .filter_map(|retained| retained.build_checkpoint().cloned())
            .collect::<Vec<_>>()
    };

    let execution = VectorStepResult::ordinary(IndexOperationStepResult::Progressed(
        first.progress().clone(),
    ))
    .retaining(
        &first,
        &first_record,
        cache.checkout_fresh::<Euclidean>().await,
    )
    .into_execution();
    assert!(format!("{execution:?}").contains("CommittedStepState::VectorBuild"));
    let validate = IndexOperationStepResult::Progressed(IndexOperationProgress::VectorBuild(
        VectorBuildProgress::Constructing(VectorBuildStage::ValidateDescriptor(
            PrefixScanProgress {
                cursor: None,
                counters: OperationCounters::default(),
            },
        )),
    ));
    for result in [validate, IndexOperationStepResult::TransientFailure] {
        let execution = VectorStepResult::ordinary(result)
            .retaining(
                &first,
                &first_record,
                cache.checkout_fresh::<Euclidean>().await,
            )
            .into_execution();
        assert!(
            !format!("{execution:?}").contains("CommittedStepState::VectorBuild"),
            "no later step checks out this session"
        );
    }

    assert_eq!(
        checked_out_simhashes::<Euclidean>(&cache, &checkpoint).await,
        0
    );
    for committed in [
        CommittedOperationStep::Blocked,
        CommittedOperationStep::Completed,
        CommittedOperationStep::TransientFailure,
    ] {
        cache
            .after_commit(first.operation_id(), committed, marked(&checkpoint))
            .await;
        assert!(retained_checkpoints().is_empty(), "{committed:?}");
    }

    cache
        .after_commit(
            first.operation_id(),
            CommittedOperationStep::Progressed,
            marked(&checkpoint),
        )
        .await;
    assert_eq!(
        checked_out_simhashes::<Euclidean>(&cache, &checkpoint).await,
        MARKED
    );
    assert!(retained_checkpoints().is_empty());

    cache
        .after_commit(
            first.operation_id(),
            CommittedOperationStep::Progressed,
            marked(&checkpoint),
        )
        .await;
    assert_eq!(
        checked_out_simhashes::<vector::distance::Cosine>(&cache, &checkpoint).await,
        0
    );

    cache
        .after_commit(
            first.operation_id(),
            CommittedOperationStep::Progressed,
            marked(&checkpoint),
        )
        .await;
    assert_eq!(
        checked_out_simhashes::<Euclidean>(&cache, &other_operation).await,
        0
    );
    assert_eq!(retained_checkpoints(), vec![checkpoint.clone()]);
    cache
        .after_commit(
            second.operation_id(),
            CommittedOperationStep::Progressed,
            None,
        )
        .await;
    assert_eq!(retained_checkpoints(), vec![checkpoint.clone()]);

    assert_eq!(
        checked_out_simhashes::<Euclidean>(&cache, &advanced).await,
        0
    );
    assert!(retained_checkpoints().is_empty());

    cache
        .after_commit(
            first.operation_id(),
            CommittedOperationStep::Progressed,
            marked(&checkpoint),
        )
        .await;
    cache
        .after_commit(
            first.operation_id(),
            CommittedOperationStep::Progressed,
            None,
        )
        .await;
    assert!(retained_checkpoints().is_empty());

    cache
        .after_commit(
            first.operation_id(),
            CommittedOperationStep::Progressed,
            marked(&checkpoint),
        )
        .await;
    cache
        .after_commit(
            second.operation_id(),
            CommittedOperationStep::Progressed,
            marked(&other_operation),
        )
        .await;
    assert_eq!(
        retained_checkpoints(),
        vec![checkpoint.clone(), other_operation.clone()]
    );
    assert_eq!(
        checked_out_simhashes::<Euclidean>(&cache, &other_operation).await,
        MARKED
    );
    assert_eq!(
        checked_out_simhashes::<Euclidean>(&cache, &checkpoint).await,
        MARKED
    );

    // Planning errors cross the step unchanged, before any session is offered.
    let ValidatedDynamicIndexDefinition::Vector(definition) = first_record.definition() else {
        panic!("contract index is a vector index");
    };
    let transaction = db
        .begin(IsolationLevel::Snapshot)
        .await
        .expect("contract step transaction opens");
    assert!(matches!(
        step_build::<Euclidean>(
            &db,
            &transaction,
            scope,
            &first,
            &first_record,
            definition,
            &VectorBuildStage::Scan(SourceScanProgress {
                inclusive_upper_bound: source_cursor(1),
                cursor: Some(source_cursor(2)),
                counters: OperationCounters::default(),
            }),
            SearchIndexBackfillLimits::default().batch(),
            IndexLifecycleScanTuning::default(),
            Arc::new(vector::SimHasherRegistry::default()),
            crate::batch_reads::BatchReads::Single,
            &cache,
        )
        .await,
        Err(HelixDbError::IndexCatalogCorruption(_))
    ));
    db.close().await.expect("contract database closes");
    // A scan that still has source rows to read reaches closed storage.
    assert!(step_build::<Euclidean>(
        &db,
        &transaction,
        scope,
        &first,
        &first_record,
        definition,
        &VectorBuildStage::Scan(SourceScanProgress {
            inclusive_upper_bound: source_cursor(1),
            cursor: None,
            counters: OperationCounters::default(),
        }),
        SearchIndexBackfillLimits::default().batch(),
        IndexLifecycleScanTuning::default(),
        Arc::new(vector::SimHasherRegistry::default()),
        crate::batch_reads::BatchReads::Single,
        &cache,
    )
    .await
    .is_err());

    budget_contracts(&first, &first_record).await;
}

/// Bytes one retained session of `simhashes` fixture SimHashes charges: its
/// namespace plus one SimHash entry each.
const fn session_bytes(simhashes: usize) -> usize {
    4_096 + simhashes * (104 + core::mem::size_of::<u64>())
}

/// Offers a build session of `simhashes` fixture SimHashes, created under a
/// 1 MiB budget, as committed at `checkpoint`.
fn build_offer(
    cache: &VectorBuildCache,
    checkpoint: &VectorBuildCheckpoint,
    simhashes: u64,
) -> Option<CommittedStepState> {
    Some(CommittedStepState::VectorBuild(Box::new(
        OfferedVectorBuild::for_tests(
            cache,
            VectorPlanningCheckpoint::Build(checkpoint.clone()),
            Box::new(VectorBuildSession::<Euclidean>::with_test_simhashes(
                NonZeroU64::new(1 << 20).expect("session budget is positive"),
                simhashes,
            )),
        ),
    )))
}

/// Retains a publication session of `simhashes` fixture SimHashes for `target`.
async fn retain_publication(
    cache: &VectorBuildCache,
    gates: &IndexScopeGates,
    target: QueueTarget,
    revision: crate::index_lifecycle::IndexRevision,
    simhashes: u64,
    backlog: PublicationBacklog,
) {
    let permit = gates.publication_permit(target).await;
    let offered = OfferedVectorBuild::for_tests(
        cache,
        VectorPlanningCheckpoint::Publication(VectorPublicationCheckpoint {
            target,
            index_record_revision: revision,
            commit: NonZeroU64::MIN,
        }),
        Box::new(VectorBuildSession::<Euclidean>::with_test_simhashes(
            NonZeroU64::new(1 << 20).expect("session budget is positive"),
            simhashes,
        )),
    );
    cache.retain_publication(&permit, offered, backlog).await;
}

/// Returns the queue target of fixture index `index`.
fn publication_target(index: u64) -> QueueTarget {
    QueueTarget::new(
        DataScope::LegacyUnscoped,
        IndexId::new(index).expect("fixture index id is positive"),
        IndexGenerationId::initial(),
    )
}

/// Returns the bytes of every retained session, least recently committed first.
fn retained_sizes(cache: &VectorBuildCache) -> Vec<usize> {
    cache
        .retained
        .try_lock()
        .expect("no rebalance is trimming the retained sessions")
        .iter()
        .map(|retained| retained.session.retained_bytes())
        .collect()
}

/// Returns the targets of every retained publication session, none of which
/// reports a build checkpoint.
fn retained_publications(cache: &VectorBuildCache) -> Vec<QueueTarget> {
    cache
        .retained
        .try_lock()
        .expect("no rebalance is trimming the retained sessions")
        .iter()
        .filter_map(|retained| match &retained.checkpoint {
            VectorPlanningCheckpoint::Publication(checkpoint) => {
                assert!(retained.build_checkpoint().is_none());
                Some(checkpoint.target)
            }
            VectorPlanningCheckpoint::Build(_) => None,
        })
        .collect()
}

/// Proves the shared planning budget bounds, trims, and rebinds sessions.
///
/// Builds beyond the retained-build bound evict the least recently committed
/// build. Publication commits beyond their bound evict the oldest drained
/// session, or are dropped when every retained target still has work. A
/// commit that leaves sessions over their max-min fair share trims them on
/// the blocking pool, and a drained session left no spare budget is dropped.
/// A checkout shrinks a reused session to the class caps of its share, and a
/// checked-out session shrinks at its next entity boundary when its share
/// fell, keeping everything when it rose. A shrink that panics on the
/// blocking pool resumes the panic in the caller, and one that fails yields
/// no session.
async fn budget_contracts(operation: &IndexOperationRecord, record: &IndexRecordV2) {
    let first = VectorBuildCheckpoint::new(operation, record, operation.progress().clone());
    let another = || VectorBuildCheckpoint {
        operation_id: IndexOperationId::new_v4(),
        ..first.clone()
    };

    // The retained-build bound evicts the least recently committed build.
    let cache = VectorBuildCache::new(NonZeroU64::new(1 << 20).expect("budget is positive"));
    let checkpoints = core::iter::once(first.clone())
        .chain((0..MAX_RETAINED_VECTOR_BUILDS).map(|_| another()))
        .collect::<Vec<_>>();
    for checkpoint in &checkpoints {
        cache
            .after_commit(
                checkpoint.operation_id,
                CommittedOperationStep::Progressed,
                build_offer(&cache, checkpoint, 0),
            )
            .await;
    }
    assert_eq!(
        cache
            .retained
            .try_lock()
            .expect("no rebalance is trimming the retained sessions")
            .iter()
            .filter_map(|retained| retained.build_checkpoint().cloned())
            .collect::<Vec<_>>(),
        checkpoints[1..].to_vec()
    );

    // Past the publication bound the oldest drained session is evicted; with
    // every retained target pending, the newest session is dropped instead.
    let gates = IndexScopeGates::default();
    let cache = VectorBuildCache::new(NonZeroU64::new(1 << 20).expect("budget is positive"));
    let bound = u64::try_from(MAX_RETAINED_PUBLICATIONS).expect("bound fits u64");
    for index in 1..bound {
        retain_publication(
            &cache,
            &gates,
            publication_target(index),
            record.revision(),
            0,
            PublicationBacklog::Pending,
        )
        .await;
    }
    for (index, backlog) in [
        (bound, PublicationBacklog::Drained),
        (bound + 1, PublicationBacklog::Pending),
        (bound + 2, PublicationBacklog::Pending),
    ] {
        retain_publication(
            &cache,
            &gates,
            publication_target(index),
            record.revision(),
            0,
            backlog,
        )
        .await;
    }
    assert_eq!(
        retained_publications(&cache),
        (1..bound)
            .chain([bound + 1])
            .map(publication_target)
            .collect::<Vec<_>>()
    );

    // Two builds over half the budget each are trimmed to their fair share,
    // and a drained session no longer fits the budget they leave.
    const TRIMMED_BUDGET: usize = 64 * 1024;
    let cache = VectorBuildCache::new(
        NonZeroU64::new(u64::try_from(TRIMMED_BUDGET).expect("budget fits u64"))
            .expect("budget is positive"),
    );
    let second = another();
    for checkpoint in [&first, &second] {
        cache
            .after_commit(
                checkpoint.operation_id,
                CommittedOperationStep::Progressed,
                build_offer(&cache, checkpoint, 400),
            )
            .await;
    }
    let sizes = retained_sizes(&cache);
    assert_eq!(sizes.len(), 2);
    assert!(
        sizes
            .iter()
            .all(|size| *size <= TRIMMED_BUDGET / 2 && *size < session_bytes(400)),
        "{sizes:?}"
    );
    retain_publication(
        &cache,
        &gates,
        publication_target(1),
        record.revision(),
        100,
        PublicationBacklog::Drained,
    )
    .await;
    assert!(retained_sizes(&cache).iter().sum::<usize>() <= TRIMMED_BUDGET);
    assert!(
        retained_sizes(&cache)
            .get(2)
            .is_none_or(|drained| *drained < session_bytes(100)),
        "a drained session keeps only spare budget"
    );

    // A reused session is shrunk to the class caps of its share at checkout.
    const CHECKOUT_BUDGET: u64 = 128 * 1024;
    let cache = VectorBuildCache::new(NonZeroU64::new(CHECKOUT_BUDGET).expect("positive"));
    cache
        .after_commit(
            first.operation_id,
            CommittedOperationStep::Progressed,
            build_offer(&cache, &first, 400),
        )
        .await;
    assert_eq!(retained_sizes(&cache), vec![session_bytes(400)]);
    let reused = cache.checkout::<Euclidean>(&first).await;
    assert!(
        (1..400).contains(&reused.simhash_count()),
        "{}",
        reused.simhash_count()
    );
    drop(reused);

    // A checked-out session shrinks at its next entity when its share falls
    // and keeps every entry when it rises again.
    let mut planning = cache.checkout_fresh::<Euclidean>().await;
    planning.session = VectorBuildSession::with_test_simhashes(
        NonZeroU64::new(1 << 20).expect("session budget is positive"),
        100,
    );
    let joining = cache.checkout_fresh::<Euclidean>().await;
    planning.rebind().await;
    let halved = planning.simhash_count();
    assert!((1..100).contains(&halved), "{halved}");
    assert_eq!(planning.bound.get(), CHECKOUT_BUDGET / 2);
    drop(joining);
    retain_publication(
        &cache,
        &gates,
        publication_target(2),
        record.revision(),
        0,
        PublicationBacklog::Pending,
    )
    .await;
    planning.rebind().await;
    assert!(planning.bound.get() > CHECKOUT_BUDGET / 2);
    assert_eq!(planning.simhash_count(), halved);
    drop(planning);

    // Shrinks run on the blocking pool: a failure yields no session and a
    // panic resumes in the caller.
    assert!(
        shrink_off_executor(0_u8, |_| Err(corruption("contract shrink fails")))
            .await
            .is_none()
    );
    let panicked = futures::FutureExt::catch_unwind(std::panic::AssertUnwindSafe(
        shrink_off_executor(0_u8, |_| panic!("contract shrink panics")),
    ))
    .await;
    assert!(panicked.is_err(), "a panicking shrink resumes its panic");
}

//! Compile-tested mirror of the Usage example in
//! [`helix-dsl-macros/README.md`](../helix-dsl-macros/README.md).
//!
//! `#[query]` helpers return `Result<QueryRequest, QueryError>`.

#![recursion_limit = "256"]

use helix_db::dsl::prelude::*;

#[query]
fn find_user(username: String) -> ReadBatch {
    read_batch()
        .var_as(
            "user",
            g().n_where(SourcePredicate::eq("username", username)),
        )
        .returning(["user"])
}

#[query]
fn create_post(title: String) -> WriteBatch {
    write_batch()
        .var_as("post", g().add_n("Post", vec![("title", title)]))
        .returning(["post"])
}

fn main() -> Result<(), QueryError> {
    let request = find_user("alice".to_string())?;
    assert_eq!(request.query_name(), Some("find_user"));

    let request = create_post("hello".to_string())?;
    assert_eq!(request.query_name(), Some("create_post"));
    Ok(())
}

